// This file is generated by AI.

// 最近项目列表 (读取迁移、搜索、排序、封面路径、相对时间) 的断言。

import { describe, expect, it } from 'vitest';

import {
  coverRelativePath,
  filterRecentProjects,
  formatRelativeTime,
  normalizeRecentProjects,
  projectDisplayName,
  RECENT_PROJECT_LIMIT,
  removeRecentProject,
  sortRecentProjects,
  upsertRecentProject,
  type RecentProject,
} from '../src/lib/recentProjects';

const project = (path: string, lastOpened: number, extra: Partial<RecentProject> = {}): RecentProject => ({
  path,
  lastOpened,
  ...extra,
});

describe('normalizeRecentProjects', () => {
  it('把旧的字符串数组升级成记录', () => {
    const list = normalizeRecentProjects(['C:\\a', 'C:\\b']);
    expect(list.map((item) => item.path)).toEqual(['C:\\a', 'C:\\b']);
    expect(list[0].lastOpened).toBeGreaterThanOrEqual(list[1].lastOpened);
  });

  it('丢弃无法识别的条目', () => {
    expect(normalizeRecentProjects([null, 42, { path: '' }, { path: 'C:\\ok' }])).toHaveLength(1);
  });

  it('同一路径大小写不同只保留一条', () => {
    expect(normalizeRecentProjects(['C:\\A', 'c:\\a'])).toHaveLength(1);
  });

  it('超出上限时截断', () => {
    const many = Array.from({ length: RECENT_PROJECT_LIMIT + 5 }, (_, index) => `C:\\p${index}`);
    expect(normalizeRecentProjects(many)).toHaveLength(RECENT_PROJECT_LIMIT);
  });

  it('不是数组时返回空列表', () => {
    expect(normalizeRecentProjects(undefined)).toEqual([]);
    expect(normalizeRecentProjects({})).toEqual([]);
  });
});

describe('sortRecentProjects / filterRecentProjects', () => {
  const list = [
    project('C:\\a', 1, { name: '星海叙事', description: '科幻' }),
    project('C:\\b', 3, { name: 'Lesson', description: '教学样例' }),
    project('C:\\c', 2),
  ];

  it('按上次打开时间倒序', () => {
    expect(sortRecentProjects(list).map((item) => item.path)).toEqual(['C:\\b', 'C:\\c', 'C:\\a']);
  });

  it('名称与路径参与搜索且大小写不敏感, 简介不参与', () => {
    expect(filterRecentProjects(list, '星海').map((item) => item.path)).toEqual(['C:\\a']);
    expect(filterRecentProjects(list, 'lesson').map((item) => item.path)).toEqual(['C:\\b']);
    expect(filterRecentProjects(list, 'c:\\c').map((item) => item.path)).toEqual(['C:\\c']);
    // "教学样例" 只是简介, 卡片上不显示, 因此不该被搜出来
    expect(filterRecentProjects(list, '教学样例')).toEqual([]);
  });

  it('空查询返回原列表', () => {
    expect(filterRecentProjects(list, '   ')).toHaveLength(3);
  });

  it('没有匹配时返回空', () => {
    expect(filterRecentProjects(list, '不存在')).toEqual([]);
  });
});

describe('upsertRecentProject', () => {
  it('新增项目并置于最前', () => {
    const next = upsertRecentProject([project('C:\\a', 1)], 'C:\\b', { name: 'B' });
    expect(next.map((item) => item.path)).toEqual(['C:\\b', 'C:\\a']);
    expect(next[0].name).toBe('B');
  });

  it('同名路径大小写不同也算同一个项目', () => {
    const next = upsertRecentProject([project('C:\\A', 1)], 'c:\\a');
    expect(next).toHaveLength(1);
  });

  it('元数据缺省时保留原值', () => {
    const next = upsertRecentProject([project('C:\\a', 1, { name: '旧名', titleImg: 'cover.png' })], 'C:\\a');
    expect(next[0].name).toBe('旧名');
    expect(next[0].titleImg).toBe('cover.png');
  });
});

describe('removeRecentProject / projectDisplayName', () => {
  it('只从列表里移除', () => {
    expect(removeRecentProject([project('C:\\a', 1), project('C:\\b', 2)], 'c:\\A').map((item) => item.path)).toEqual([
      'C:\\b',
    ]);
  });

  it('没有游戏名时显示目录名', () => {
    expect(projectDisplayName(project('C:\\proj\\我的游戏', 1))).toBe('我的游戏');
    expect(projectDisplayName(project('C:\\proj\\x', 1, { name: '星海' }))).toBe('星海');
  });
});

describe('coverRelativePath', () => {
  it('拼出 game/background 下的相对路径', () => {
    expect(coverRelativePath('cover.png')).toBe('game/background/cover.png');
    expect(coverRelativePath('sub/cover.png')).toBe('game/background/sub/cover.png');
  });

  it('没有配置或试图跳出资源目录时返回 null', () => {
    expect(coverRelativePath(undefined)).toBeNull();
    expect(coverRelativePath('   ')).toBeNull();
    expect(coverRelativePath('../../etc/passwd')).toBeNull();
  });
});

describe('formatRelativeTime', () => {
  const now = new Date('2026-01-10T12:00:00Z').getTime();

  it('按量级给出中文描述', () => {
    expect(formatRelativeTime(now - 5_000, now)).toBe('刚刚');
    expect(formatRelativeTime(now - 5 * 60_000, now)).toBe('5 分钟前');
    expect(formatRelativeTime(now - 3 * 3_600_000, now)).toBe('3 小时前');
    expect(formatRelativeTime(now - 2 * 86_400_000, now)).toBe('2 天前');
  });

  it('超过一个月显示具体日期', () => {
    expect(formatRelativeTime(Date.parse('2025-02-03T00:00:00Z'), now)).toMatch(/^2025-02-0[23]$/);
  });
});
